import{_ as t,o as i,c as a,ag as s}from"./chunks/framework.CbQjVMS6.js";const g=JSON.parse('{"title":"RAG vs. LLM wiki: two ways to give agents knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"insights/rag-vs-llm-wiki.md","filePath":"insights/rag-vs-llm-wiki.md","lastUpdated":1793948662000}'),o={name:"insights/rag-vs-llm-wiki.md"};function r(n,e,l,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="rag-vs-llm-wiki-two-ways-to-give-agents-knowledge" tabindex="-1">RAG vs. LLM wiki: two ways to give agents knowledge <a class="header-anchor" href="#rag-vs-llm-wiki-two-ways-to-give-agents-knowledge" aria-label="Permalink to &quot;RAG vs. LLM wiki: two ways to give agents knowledge&quot;">​</a></h1><p><em>Published 6 November 2026 · 8 min read</em></p><p>Retrieval-augmented generation (RAG) and an LLM-maintained wiki are often presented as competing answers to the same question: how do we give a model access to our documents? In practice they optimise for different things, and the right architecture usually borrows from both.</p><h2 id="the-standard-rag-pipeline" tabindex="-1">The standard RAG pipeline <a class="header-anchor" href="#the-standard-rag-pipeline" aria-label="Permalink to &quot;The standard RAG pipeline&quot;">​</a></h2><p>A conventional RAG system has four stages:</p><ol><li><strong>Ingest</strong> documents and split them into chunks.</li><li><strong>Embed</strong> each chunk into a vector.</li><li><strong>Retrieve</strong> the top-k chunks for a query.</li><li><strong>Generate</strong> an answer conditioned on those chunks.</li></ol><p>This pipeline is popular because it is easy to start and works reasonably well for questions whose answer lives in a single passage. It does not require anyone to organise the corpus, and it scales to large collections without manual authoring.</p><p>Its weaknesses appear as soon as questions become multi-hop or evidence-sensitive:</p><ul><li><strong>Chunk boundaries cut through meaning.</strong> A procedure split across three chunks may never be retrieved as a whole.</li><li><strong>No stable identity.</strong> A chunk is an artifact of the splitter, not a topic. You cannot link to it, cite it cleanly or update it deliberately.</li><li><strong>Duplication and contradiction.</strong> Two documents may say different things; the retriever returns both and the model averages them.</li><li><strong>Opaque relevance.</strong> Similarity scores are hard to explain to a user or an auditor.</li><li><strong>Index drift.</strong> Re-embedding is expensive, and stale chunks survive quietly.</li></ul><p>None of these are fatal. They are the cost of avoiding curation.</p><h2 id="the-wiki-approach" tabindex="-1">The wiki approach <a class="header-anchor" href="#the-wiki-approach" aria-label="Permalink to &quot;The wiki approach&quot;">​</a></h2><p>An LLM wiki takes a different route. Instead of indexing raw chunks, it distills source documents into structured pages: one page per source note, plus concept pages that synthesize multiple sources. Those pages are the retrieval unit.</p><p>The pipeline becomes:</p><ol><li><strong>Ingest</strong> a source document.</li><li><strong>Distill</strong> it into a structured note with citations.</li><li><strong>Synthesize</strong> concept, comparison or decision pages from multiple notes.</li><li><strong>Index</strong> the resulting pages with lexical and structural search.</li><li><strong>Read</strong> the pages in full when an agent requests them.</li></ol><p>The important difference is that the knowledge layer is an artifact a human can inspect. Pages have titles, links and sources. Changes are visible in version control. Contradictions can be resolved instead of averaged.</p><p>The cost is maintenance. Distillation takes compute or human time, and a wiki can rot if nobody reviews it. An LLM wiki also inherits the model&#39;s mistakes: a confidently wrong summary is worse than an unsummarised source. This is why the output should remain reviewable Markdown with explicit source links.</p><h2 id="a-side-by-side-comparison" tabindex="-1">A side-by-side comparison <a class="header-anchor" href="#a-side-by-side-comparison" aria-label="Permalink to &quot;A side-by-side comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Chunk-based RAG</th><th>LLM wiki</th></tr></thead><tbody><tr><td>Retrieval unit</td><td>Arbitrary chunk</td><td>Stable page</td></tr><tr><td>Authoring effort</td><td>Low at ingest</td><td>Higher: distillation and review</td></tr><tr><td>Multi-hop questions</td><td>Weak unless the agent iterates</td><td>Strong: pages link to related pages</td></tr><tr><td>Citation quality</td><td>Chunk-level, often ambiguous</td><td>Page-level with source links</td></tr><tr><td>Auditability</td><td>Low</td><td>High: diffable Markdown</td></tr><tr><td>Freshness</td><td>Re-embedding pipeline</td><td>Rebuild affected pages</td></tr><tr><td>Failure mode</td><td>Retrieves plausible but incomplete context</td><td>Distills confidently wrong pages</td></tr><tr><td>Best fit</td><td>Large, fast-changing, loosely structured corpora</td><td>Curated domains where correctness matters</td></tr></tbody></table><h2 id="they-are-not-mutually-exclusive" tabindex="-1">They are not mutually exclusive <a class="header-anchor" href="#they-are-not-mutually-exclusive" aria-label="Permalink to &quot;They are not mutually exclusive&quot;">​</a></h2><p>The useful question is not “RAG or wiki?” but “what should the agent retrieve, and what should it read?”</p><p>A strong architecture often looks like this:</p><ul><li><strong>Wiki pages as the primary unit.</strong> Distill high-value sources into readable pages with citations.</li><li><strong>Lexical search as the baseline.</strong> BM25 handles identifiers, names and exact phrases that embeddings miss.</li><li><strong>Optional embeddings as a second channel.</strong> Use them for paraphrase matching, then fuse results with reciprocal rank fusion.</li><li><strong>Structure-aware ranking.</strong> Prefer pages with more sources, better links and recent review dates.</li><li><strong>Full-page reading.</strong> Once a page is selected, give the agent the whole page rather than another fragment.</li></ul><p>This is the design PieKBS follows. It is deliberately local-first: SQLite FTS5 for search, files on disk for storage, MCP for access. You can add a vector index later without changing the knowledge model.</p><h2 id="how-to-choose" tabindex="-1">How to choose <a class="header-anchor" href="#how-to-choose" aria-label="Permalink to &quot;How to choose&quot;">​</a></h2><p>Choose <strong>chunk-based RAG</strong> when:</p><ul><li>the corpus is large, heterogeneous and changes constantly</li><li>questions are mostly single-passage lookups</li><li>you cannot afford curation</li><li>you need a working prototype quickly</li></ul><p>Choose an <strong>LLM wiki</strong> when:</p><ul><li>correctness and provenance matter more than coverage</li><li>the same concepts recur across documents and need synthesis</li><li>agents must read complete procedures or policies</li><li>humans need to review and correct what the system knows</li><li>the corpus is bounded enough to maintain</li></ul><p>Many teams end up with a hybrid: a curated wiki for core knowledge, and vector search over an archive of raw documents for long-tail recall. The wiki provides quality; the archive provides coverage. Keeping the two layers distinct avoids the common failure where curated and uncurated content compete in the same index.</p><h2 id="operational-checklist" tabindex="-1">Operational checklist <a class="header-anchor" href="#operational-checklist" aria-label="Permalink to &quot;Operational checklist&quot;">​</a></h2><ul><li><strong>Keep the source of truth.</strong> Never let the distilled page become the only copy of a document.</li><li><strong>Record the model and prompt.</strong> A distillation is reproducible only if you know how it was produced.</li><li><strong>Track page freshness.</strong> Surface the last review date and the age of the underlying sources.</li><li><strong>Measure retrieval, not just answers.</strong> Log which pages were returned, which were read and which were cited.</li><li><strong>Review contradictions.</strong> A wiki should make disagreement visible, not resolve it silently.</li><li><strong>Plan for deletion.</strong> Sources expire; pages must be removable without leaving orphan claims.</li></ul><p>The deepest difference between the two approaches is philosophical. Chunk-based RAG treats knowledge as a search problem. An LLM wiki treats knowledge as an editorial artifact. Agents need both good search and good material; the second is harder to build and more valuable when it works.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://pieteams.github.io/piekbs/ecosystem/paradigm-comparison" target="_blank" rel="noreferrer">PieKBS ecosystem comparison</a> — a wider survey of RAG and wiki systems</li><li><a href="/insights/agent-native-knowledge">Why agents need a search engine</a> — the retrieval loop</li><li><a href="https://pieteams.github.io/piekbs/guide/knowledge-pipeline" target="_blank" rel="noreferrer">PieKBS knowledge pipeline</a> — distillation in practice</li></ul>',34)])])}const p=t(o,[["render",r]]);export{g as __pageData,p as default};
